var CET_LISTENING = {"cet4-mock-l1":{"id":"cet4-mock-l1","level":"cet4","year":2026,"month":1,"set":1,"mock":true,"sections":[{"name":"Section A","questions":[{"n":1,"group":"第1-2题","options":{"A":"It has moved into a larger building near the park.","B":"It has opened a night study area and stays open later.","C":"It has started charging a fee for its study rooms.","D":"It has bought more computers for public use."}},{"n":2,"group":"第1-2题","options":{"A":"They must be full-time students of the city.","B":"They must arrive before eight in the evening.","C":"They must book a seat online in advance.","D":"They must pay a small amount each day."}},{"n":3,"group":"第3-4题","options":{"A":"Recycled paper collected from offices.","B":"Fibres taken from grain stalks.","C":"Thin sheets cut from bamboo.","D":"Plastic gathered from the coast."}},{"n":4,"group":"第3-4题","options":{"A":"Keeping food fresh for a longer time.","B":"Making the material strong enough.","C":"Bringing the cost of the material down.","D":"Finding a company willing to test it."}},{"n":5,"group":"第5-7题","options":{"A":"From five in the morning until four in the afternoon.","B":"From seven thirty in the morning until noon.","C":"From midnight until six in the evening.","D":"From four in the afternoon until midnight."}},{"n":6,"group":"第5-7题","options":{"A":"By showing their identity cards at the roadside.","B":"By collecting a pass from the community office.","C":"By joining a car-sharing scheme for residents.","D":"By applying online on the morning of the race."}},{"n":7,"group":"第5-7题","options":{"A":"Take the ring road and allow more time for the journey.","B":"Park their cars near the north gate of the city.","C":"Use the bus routes running through the eastern districts.","D":"Avoid travelling at all before seven thirty that morning."}}]},{"name":"Section B","questions":[{"n":8,"group":"第8-11题","options":{"A":"To ask about the essay she handed in last week.","B":"To talk about her course plan for next term.","C":"To complain about a clash in the timetable.","D":"To ask for more time to finish an assignment."}},{"n":9,"group":"第8-11题","options":{"A":"Fifty-eight.","B":"Sixty-two.","C":"One hundred and twenty.","D":"Three."}},{"n":10,"group":"第8-11题","options":{"A":"It is much easier than the writing course.","B":"It is offered in the autumn term only.","C":"It is a required course for her major.","D":"It has far fewer reading assignments."}},{"n":11,"group":"第8-11题","options":{"A":"It is a prerequisite for two later courses.","B":"It is taught by a very strict teacher.","C":"It cannot be dropped after the first week.","D":"It counts double towards her average."}},{"n":12,"group":"第12-15题","options":{"A":"It has risen to four hundred and eighty a month.","B":"It now includes all the bills for the flat.","C":"It is lower than the two of them expected.","D":"It has to be paid a full year in advance."}},{"n":13,"group":"第12-15题","options":{"A":"The flat is too far away from the university.","B":"The landlord may refuse to sign a contract.","C":"The housework will not be shared fairly.","D":"The deposit is more than they can afford."}},{"n":14,"group":"第12-15题","options":{"A":"Divide the six jobs and swap them every month.","B":"Hire someone to clean the bathroom each week.","C":"Let the woman do all of the cooking herself.","D":"Take turns doing everything for a whole week."}},{"n":15,"group":"第12-15题","options":{"A":"Guests must leave before eleven on weeknights.","B":"Guests are not allowed at weekends at all.","C":"Guests must pay a share of the monthly bills.","D":"Guests may stay only if the landlord agrees."}}]},{"name":"Section C","questions":[{"n":16,"group":"第16-18题","options":{"A":"Reading enough about the company.","B":"Preparing evidence to support their answers.","C":"Arriving well before the interview starts.","D":"Learning the names of the interviewers."}},{"n":17,"group":"第16-18题","options":{"A":"To check how long each of the answers takes.","B":"To find the parts of the story still unclear.","C":"To improve the pronunciation of hard words.","D":"To send the recording to the employer later."}},{"n":18,"group":"第16-18题","options":{"A":"A question about salary and holiday arrangements.","B":"A question about something on the company website.","C":"A question about what the team found difficult.","D":"A question about when the result will be announced."}},{"n":19,"group":"第19-21题","options":{"A":"The timing of sleep.","B":"The temperature of the bedroom.","C":"The amount of exercise in the day.","D":"The food eaten just before bedtime."}},{"n":20,"group":"第19-21题","options":{"A":"They need fewer hours of sleep for a week.","B":"They may lose concentration in the morning.","C":"They become far more sensitive to noise.","D":"They wake up earlier without using an alarm."}},{"n":21,"group":"第19-21题","options":{"A":"The light harms the eyes over a long period.","B":"It keeps the mind in its daytime state.","C":"It makes the bedroom too warm at night.","D":"It reduces the quality of sleep and dreams."}},{"n":22,"group":"第22-25题","options":{"A":"Students were riding the bicycles too fast.","B":"Bicycles were left in doorways and on ramps.","C":"Too many of the bicycles were being stolen.","D":"Students were taking bicycles into the city."}},{"n":23,"group":"第22-25题","options":{"A":"They have to pay a larger deposit.","B":"Their account is suspended for a month.","C":"They lose the right to ride at weekends.","D":"They are reported to their own department."}},{"n":24,"group":"第22-25题","options":{"A":"Leave it at the nearest marked parking area.","B":"Report it through the app and ride for free.","C":"Take it to the company office by themselves.","D":"Pay for the repair and claim the money back."}},{"n":25,"group":"第22-25题","options":{"A":"They fell by a third after the rules came in.","B":"They were mostly caused by broken brakes.","C":"They doubled during the first month.","D":"They happened mainly at the main gate."}}]}],"transcripts":{"第1-2题":["A community library in the Northfield district of Riverside City has extended its opening hours until ten in the evening, and has turned a former storage room on the second floor into a night study area. The change took effect at the start of this month. Library staff say the number of visitors after eight in the evening has nearly doubled since then, and most of them are students preparing for examinations. The night area has forty desks, reading lamps and a small kitchen where visitors can make tea. It is open to anyone with a library card, but seats must be booked online, and each booking is limited to three hours a day. The library says the new hours will be reviewed after six months, and if demand stays high the same arrangement may be introduced at two other branches."],"第3-4题":["Three students at Northfield University have designed a food packaging material that breaks down in soil within eight weeks. The material is made mainly from the fibres of grain stalks left over after harvest, mixed with a small amount of plant-based glue. In tests, the team wrapped sandwiches and fresh fruit in the material and kept them at room temperature. The packaging held its shape for four days and began to soften only after moisture reached the inner layer. Their supervisor says the hardest part was not making the material strong, but making it cheap enough to compete with ordinary plastic film. A local bakery has agreed to trial the packaging for three months from March. The team has also applied for a grant to buy a machine that can produce the material in larger sheets."],"第5-7题":["Riverside City will hold its annual marathon on Sunday, the twelfth of April, and the city traffic office has announced a series of road closures. From five in the morning until four in the afternoon, vehicles will not be allowed on the riverside road between the old bridge and the north gate. Six bus routes will be shortened and three will run on temporary routes through the eastern districts. The organisers expect about eighteen thousand runners, and the race will start at seven thirty. Residents who live inside the closed area will be given passes for their cars, but the passes must be collected from the community office before Friday. Ambulance and fire services will keep one lane open at all times. The traffic office advises drivers to use the ring road and to allow an extra thirty minutes for journeys on Sunday."],"第8-11题":["W: Professor Hale, do you have a minute? I am Mia Chen, from the second-year literature group. M: Of course, Mia. Sit down. Is this about the essay you handed in last week? W: No, actually, the essay is fine, I think. It is about next term. I am trying to work out my course plan, and I keep going round in circles.","M: Right. Let us have a look. How many credits have you completed so far? W: Sixty-two. I need a hundred and twenty to graduate, so fifty-eight to go, and three terms left. M: That is comfortable, but do not leave too much to the final term. What were you thinking of taking?","W: I wanted the advanced writing course, but it clashes with the statistics class I need for my major. M: Then take statistics first. The writing course runs every term; statistics does not. It is offered in the autumn only. W: Oh, I did not know that. So statistics this term, writing next autumn.","M: Exactly. And that leaves you a free slot. Have you considered the introduction to linguistics? W: I have, but it is four credits and I have heard the reading is heavy. M: It is heavy, but it is also the prerequisite for two courses you may want later.","M: If you are worried about the workload, take it as an extra course and drop it in the second week. There is no penalty for that. W: That is reassuring. And what about the community project, the one where students teach in local schools? M: Two credits, and it is pass or fail, so it will not touch your average. It is popular, though. Applications close at the end of this month.","W: Then I will apply tonight. Thank you, Professor. I feel much clearer now."],"第12-15题":["M: So, did you hear back from the landlord about the flat on Mill Street? W: I did. He says we can move in on the first of September, but the rent has gone up. It is now four hundred and eighty a month, not four hundred and fifty. M: For the whole flat, or each? W: The whole flat. So two hundred and forty each, plus bills. Honestly, that is still cheaper than the hall.","M: True. But we need to be clear about the boring stuff before we sign anything. Who does what? W: I was thinking we split it down the middle. You cook, I clean. M: That sounds fair in theory, but I know how it will go. I will cook every night, and you will clean once a week and then say you are tired.","W: That is not... okay, that is slightly fair. What do you suggest? M: Let us write a list. Cooking on weekdays, cooking at weekends, dishes, bathroom, floors and the shopping. Six jobs. We take three each, and we swap every month, so nobody is stuck with the bathroom forever.","W: I like the swap idea. Can I have the shopping? I actually enjoy it. M: Fine, but that means you also take the floors. And we need a rule for guests. W: No guests after eleven on weeknights. And whoever invites them does the extra cleaning.","M: Deal. I will write it up and send it to you tonight, and we can both sign it before we pay the deposit. W: Good. And let us keep the list on the fridge, so we cannot pretend we forgot."],"第16-18题":["Most people prepare for an interview by reading about the company. That is useful, but it is only half the work. The other half is preparing the evidence you will need to support your answers, and that takes longer than most candidates expect.","Start with three or four stories from your own experience: a project you finished, a problem you solved, a time you worked with difficult people. For each story, write down the situation, what you decided to do, and what happened in the end. Interviewers rarely remember a claim such as I am good with teams. They do remember a specific account of how you handled a disagreement, because it tells them what you would do next time.","Then practise saying those stories out loud. Reading them silently creates a false sense of readiness: the words feel familiar, but your mouth has never said them. Ten minutes of speaking to an empty room is worth an hour of reading. If you can, record yourself once and listen for the parts where you slow down or start again. Those are usually the places where your story is still unclear.","Finally, prepare two questions to ask at the end. Not about salary, and not about anything you could have found on the website. Ask what the team found difficult last year, or how success in the first six months would be judged. The questions you ask say as much about you as the answers you give."],"第19-21题":["When people say they feel tired all day, they usually blame the amount of sleep they got. Researchers who study sleep habits point out that the timing matters just as much as the length. Going to bed at midnight on Monday and at three in the morning on Saturday gives you two very different nights, and the body treats them as such.","The body follows an internal clock that expects light, meals and activity at roughly the same hours each day. When those hours move, the clock has to reset, and the reset is not instant. A single late night can shift it by an hour or more, and it may take two or three days of regular hours to bring it back. During that time, people often report poor concentration in the morning and hunger at strange times, because the hormones that control appetite follow the same clock.","The practical advice is dull but effective. Choose a waking time you can keep seven days a week, and let your bedtime adjust around it. Get daylight within an hour of waking, ideally by going outside rather than sitting by a window. And keep the last hour before bed free of bright screens, not because the light is harmful in itself, but because it keeps the mind in the state it was in during the day."],"第22-25题":["Shared bicycles appeared on the Northfield campus two years ago, and in the first month they were treated as a novelty. Students rode them to the station, left them wherever the ride ended, and by the end of the week bicycles were lying across doorways and blocking the ramps used by wheelchair users. The university then introduced a set of rules, and those rules are worth knowing before you unlock your first bicycle.","First, bicycles must be parked in one of the marked areas, which are painted white and can be found outside every teaching building and hall of residence. Leaving a bicycle outside a marked area carries a small charge, and repeated offences lead to the account being suspended for a month. Second, the bicycles are for campus use only. Riding one through the main gate and into the city is not allowed, though many students admit they have done it. Third, riders must be over sixteen, and helmets are strongly recommended but not required.","The most common complaint is not about parking but about maintenance. A bicycle with a broken brake should be reported through the app immediately, and the ride is then free. The company says it repairs reported bicycles within two working days. Last year, it says, the number of accidents on campus fell by a third after the rules came in, which is a result worth remembering the next time you are tempted to leave a bicycle in a doorway."]}},"cet4-mock-l2":{"id":"cet4-mock-l2","level":"cet4","year":2026,"month":1,"set":2,"mock":true,"sections":[{"name":"Section A","questions":[{"n":1,"group":"第1-2题","options":{"A":"It will stop offering takeaway meals altogether.","B":"It will charge a deposit on reusable cutlery.","C":"It will raise the price of hot drinks.","D":"It will close one of its two cafeterias."}},{"n":2,"group":"第1-2题","options":{"A":"It may cost the university too much money.","B":"It may not be accepted by first-year students.","C":"It may make the lunch queue move more slowly.","D":"It may create extra work for the cleaners."}},{"n":3,"group":"第3-4题","options":{"A":"Passed a written test on programming.","B":"Designed a small web page of their own.","C":"Built a mobile app for a local charity.","D":"Taught younger children some coding."}},{"n":4,"group":"第3-4题","options":{"A":"Most of its students went on to study computing at school.","B":"It was held in three different classrooms.","C":"It received money from a local company.","D":"It attracted teenagers from other towns."}},{"n":5,"group":"第5-7题","options":{"A":"To host a summer music festival.","B":"To attract more tourists to the lake.","C":"To make up for an earlier closure.","D":"To give residents a place to exercise after work."}},{"n":6,"group":"第5-7题","options":{"A":"The closing time of the boating area.","B":"The number of security guards on duty.","C":"The lighting along the main path.","D":"The opening hour of the east gate."}},{"n":7,"group":"第5-7题","options":{"A":"The cost of the new lights.","B":"The shortage of security guards.","C":"Possible noise and parking problems.","D":"The condition of the playground equipment."}}]},{"name":"Section B","questions":[{"n":8,"group":"第8-11题","options":{"A":"To book a place in a Saturday class.","B":"To find out about joining the gym.","C":"To ask whether the pool opens on Sundays.","D":"To complain that a class is already full."}},{"n":9,"group":"第8-11题","options":{"A":"It cannot be used at weekends.","B":"It costs half as much as the full one.","C":"It does not include any classes.","D":"It is open only to first-year students."}},{"n":10,"group":"第8-11题","options":{"A":"It is held twice a week.","B":"It requires a fitness test first.","C":"It is taught by two instructors.","D":"It is limited to twelve people."}},{"n":11,"group":"第8-11题","options":{"A":"Sign up for the full membership.","B":"Try a spinning class in the evening.","C":"Pay for a term of yoga classes.","D":"Ask for his deposit back."}},{"n":12,"group":"第12-15题","options":{"A":"The fast train has been cancelled.","B":"Tickets cost more than he had expected.","C":"It leaves only in the early morning.","D":"It is cheaper than it was last year."}},{"n":13,"group":"第12-15题","options":{"A":"The price is too high for her.","B":"It is a long way from the beach.","C":"The rooms are shared with other guests.","D":"Breakfast is not included."}},{"n":14,"group":"第12-15题","options":{"A":"Book it together with the hostel.","B":"Give it up to save money.","C":"Ask a friend to pay for it.","D":"Take it only if the weather is fine."}},{"n":15,"group":"第12-15题","options":{"A":"Book beds at the hostel.","B":"Buy the train tickets online.","C":"Check the weather forecast.","D":"Look for a cheaper hotel."}}]},{"name":"Section C","questions":[{"n":16,"group":"第16-18题","options":{"A":"Students seldom attend lectures regularly.","B":"Teachers speak too fast for students to follow.","C":"Notes copied word for word prove useless later.","D":"Students depend too much on slides."}},{"n":17,"group":"第16-18题","options":{"A":"It saves time during the lecture.","B":"It forces the brain to process the idea.","C":"It makes the notes easier to read.","D":"It helps you keep the teacher's exact wording."}},{"n":18,"group":"第16-18题","options":{"A":"It works better than repeated reading later.","B":"It should be done together with a classmate.","C":"It takes at least an hour to be effective.","D":"It is only useful for exam subjects."}},{"n":19,"group":"第19-21题","options":{"A":"A friend persuaded her to try it.","B":"She wanted to learn how to cook.","C":"She needed work experience for her course.","D":"She felt she ought to do something."}},{"n":20,"group":"第19-21题","options":{"A":"Grateful for the warm welcome she received.","B":"Unsure whether she would go back.","C":"Eager to take on more responsibility.","D":"Disappointed with the food she was given."}},{"n":21,"group":"第19-21题","options":{"A":"A regular and meaningful part of her week.","B":"Skills that helped her find a job.","C":"A group of close friends of her own age.","D":"A better understanding of healthy eating."}},{"n":22,"group":"第22-25题","options":{"A":"They are the same with all online sellers.","B":"They are usually shorter than a week.","C":"They may start from the day of ordering.","D":"They can be extended on request."}},{"n":23,"group":"第22-25题","options":{"A":"Shoes tried on briefly indoors.","B":"A coat that smells of perfume.","C":"A shirt with the label removed.","D":"Boots with mud on the soles."}},{"n":24,"group":"第22-25题","options":{"A":"It can be used only once.","B":"Its cost may be taken out of the refund.","C":"It takes longer to reach the seller.","D":"It requires a printer at home."}},{"n":25,"group":"第22-25题","options":{"A":"To prove what was inside the box.","B":"To show the seller the item is unused.","C":"To speed up the refund.","D":"To settle disputes if the parcel goes missing."}}]}],"transcripts":{"第1-2题":["Students at Greenhill University will notice several changes in the dining hall this term. From next Monday, the two main cafeterias will stop handing out plastic forks, knives and spoons with takeaway meals. Diners who want cutlery will pick up a reusable set at the counter and pay a deposit of two dollars, which is returned when the set comes back. Paper straws replaced the plastic ones last month, and cold drinks are now sold in cans or glass bottles instead of plastic cups. The head of campus services, Dana Whitfield, said the trial follows a survey in which nearly seventy percent of students said they would support such a move. She admitted that the deposit system might slow the lunch queue in the first few weeks, and said extra staff would be on hand to help. If the trial goes well, the university plans to extend it to the coffee shops in the library and the sports centre."],"第3-4题":["A non-profit group in the town of Westbrook is opening a free summer coding camp for teenagers aged thirteen to seventeen. The camp will run for four weeks in July, with classes on weekday mornings from nine until twelve. Students will learn the basics of building a simple website, and by the end of the course each of them will have designed a small page about a subject they care about. Organisers say there is room for sixty students and that no previous experience is required. Applications opened on Monday and will close at the end of May. Those who cannot easily travel to the town centre can take a bus that leaves from three neighbourhood schools each morning. The group's director, Peter Nash, said the camp began three years ago with twelve teenagers and a single classroom. Last summer, he added, more than half of the students who finished the course went on to take a computer science class at school."],"第5-7题":["Lakeside Park will stay open until eleven at night from this Friday, three hours later than usual, as part of a two-month trial. The city council says the aim is to give residents somewhere to walk and exercise after work, especially in the hot summer months when daytime temperatures keep many people indoors. New lights have been fitted along the main path around the lake, and two more security guards will patrol the park in the evenings. The boating area and the children's playground, however, will still close at eight, because staff are needed to check the equipment every night. Not everyone is pleased. A group of residents living near the east gate has written to the council, arguing that late-night noise and parking problems are likely to get worse. The council has promised to review the complaints after the first month and to shorten the opening hours if the disturbance becomes serious. A final decision on whether to keep the later closing time will be made in September."],"第8-11题":["W: Greenhill Sports Centre, Sophie speaking. How can I help? M: Hi, um, I am a second-year student and I was thinking of joining the gym. I mean, I have never really used one before, so I am not sure where to start. W: No problem. We have two kinds of membership. The full one is ninety dollars a term and gives you everything, the weights room, the pool and all the classes. The basic one is fifty, but it covers only the weights room and the pool.","M: Right. And, sorry, does the basic one include the pool at weekends? Someone told me it is closed on Sundays. W: The pool is open every day, but on Sunday it closes at four instead of nine. M: OK, that is fine. I think I would go for the full one, because I would like to try a class. What sort of classes are there? W: Well, there is yoga on Monday and Wednesday mornings, spinning, that is the exercise bikes, on Tuesday and Thursday evenings, and a beginners' fitness class on Saturday at ten.","M: Saturday at ten might work. Is it very hard? I am, er, not exactly fit at the moment. W: It is designed for people who have not exercised for a while. The instructor keeps the group small, twelve people at most, so she can check everyone's technique. M: Sounds good. Do I need to book, or can I just turn up? W: You need to book, and places go quickly. Booking opens a week before each class, online or at the desk.","M: Got it. And one more thing, can I pay by card, or is it cash only? W: Card is fine. If you sign up before Friday there is a ten percent discount for new members. M: Oh, nice. I will come in tomorrow then. W: Great. Ask for me at the desk."],"第12-15题":["W: So, have you looked at the train times for the trip? M: I have, and honestly it is more expensive than I expected. A return ticket to the coast is eighty dollars each. W: Eighty? That is, wow. Last year it was about fifty. M: I know. But there is a slower train that takes five hours instead of three, and that one is only forty-five.","W: Five hours is a lot. Though I suppose we could leave early and sleep on the train. What about somewhere to stay? M: That is the other thing. The hotels near the beach are all over a hundred a night. But I found a hostel about twenty minutes' walk from the water, beds from thirty dollars, and breakfast is included. W: A hostel. Hmm. Is it, you know, shared rooms? M: Four to a room. I have stayed in worse. And the reviews say it is clean, which matters more to me than privacy for two nights.","W: Fair enough. So if we take the slow train and the hostel, that is, what, about a hundred and fifty each for travel and beds? M: Closer to a hundred and sixty with the bus from the station. But we would still need food, and, um, the boat trip you wanted. W: The boat trip is sixty. I would rather skip one dinner out and do that, actually. M: Agreed. But let us not book the boat until we see the weather. If it rains, that money is gone.","W: Good point. Shall I book the hostel tonight, then? The cheap beds might go. M: Yes, do it. I will sort out the train tomorrow when I get paid. W: And I will check the forecast on Thursday. M: Perfect. Bring the details to lunch and we can work out the rest."],"第16-18题":["Most students take notes in class, but few are ever taught how to do it well. The result is often a page of sentences copied word for word from a slide, which feels productive at the time and turns out to be almost useless a month later.","Research on memory suggests three simple habits that make a real difference. The first is to write in your own words. When you rephrase an idea, your brain has to process it, and that effort is what fixes it in memory. Copying, by contrast, lets the words pass from the screen to the page without ever being understood.","The second habit is to leave space. A page packed with text gives you nowhere to add a question, an example or a correction when you review the material. Many students find that a wide margin down one side of the page is enough, and they use it later to sum up each paragraph in a single line.","The third habit is to review your notes within a day. Reading them once, twenty-four hours after the lecture, does more than reading them five times the week before an exam. The reason is that forgetting has already begun, and pulling the information back takes a little effort, the same effort that strengthens the memory. None of these habits takes extra time in class. They simply change what you do with the pen in your hand."],"第19-21题":["I spent last autumn volunteering at a community kitchen in my neighbourhood, and it changed the way I think about free time. I had signed up mostly out of guilt. A friend had been going for a year and kept saying how much she enjoyed it, and I had run out of excuses.","The first Saturday I arrived at seven in the morning, was handed an apron and a box of onions, and spent two hours cutting them. Nobody thanked me. Nobody even asked my name. I went home smelling of onions and wondering whether I would go back.","I did go back, mainly because the woman in charge, Nora, remembered me the following week and put me on the serving counter. That was different. Standing there with a ladle in my hand, I met the same faces every Saturday: a retired teacher who came for the soup and stayed for the conversation, two brothers who always arrived late, and a young father who never asked for anything for himself.","What I learned was not the lesson I expected. I had thought volunteering was about giving something up. In practice, it gave a shape to my week. Saturday morning stopped being a space I had to fill and became the part I looked forward to. I am not suggesting that everyone should spend their weekends in a kitchen. But I would say this: the first visit is the hardest, and it is worth getting through."],"第22-25题":["Buying clothes online has one obvious disadvantage: you cannot try them on. Shops know this, which is why most of them now offer free returns within a set number of days. The rules, however, differ far more than most customers realise.","The first thing to check is the deadline. Thirty days from delivery is common, but some sellers count from the day you place the order, which can take a week off your time. Second, look at what counts as 'unused'. A pair of shoes worn indoors once is usually fine; shoes with mud on the soles are not. Tags must normally still be attached, and many sellers refuse anything that smells of perfume or smoke. Most also expect the item to return in its original packaging.","Third, decide how to send the item back. A prepaid label is convenient, but the cost is sometimes deducted from your refund, so a cheaper postal service may be worth the extra walk. Keep the receipt until the money arrives. Finally, photograph the parcel before you hand it over, especially if it contains more than one item. Parcels do go missing, and a picture of the sealed box, with the label clearly visible, settles most arguments quickly. None of this takes long. Five minutes of checking before you click 'buy' will save you a month of emails later."]}},"cet6-mock-l1":{"id":"cet6-mock-l1","level":"cet6","year":2026,"month":1,"set":1,"mock":true,"sections":[{"name":"Section A","questions":[{"n":1,"stem":"What did the Brant Institute announce?","group":"第1-2题","options":{"A":"A species of mollusc new to science had been identified.","B":"A research vessel had completed its deepest dive.","C":"A known species had been found in a new habitat.","D":"A mineral vent had stopped releasing bacteria."}},{"n":2,"stem":"Why did the team fail to recognise the animal at first?","group":"第1-2题","options":{"A":"They had only a handful of photographs of it.","B":"They thought it belonged to a species already known.","C":"Its colour made it almost invisible to cameras.","D":"Another team had already collected the specimens."}},{"n":3,"stem":"What will happen in Halden from April?","group":"第3-4题","options":{"A":"Private cars will be kept out of the city centre.","B":"All delivery vehicles will be banned from the harbour.","C":"Parking permits will no longer be issued to residents.","D":"The old harbour will be closed to trams."}},{"n":4,"stem":"What did local traders fear?","group":"第3-4题","options":{"A":"That the new trams would cost too much to run.","B":"That deliveries would arrive too late in the day.","C":"That shoppers would move to retail parks outside the city.","D":"That the scheme would be reviewed too soon."}},{"n":5,"stem":"What is said about the artificial intelligence assistant?","group":"第5-7题","options":{"A":"It was built by students at the university.","B":"It can be used by first-year students at any time.","C":"It has replaced tutorials in some modules.","D":"It deals only with past examination papers."}},{"n":6,"stem":"What did last term's trial suggest?","group":"第5-7题","options":{"A":"Frequent users were slightly more likely to submit work on time.","B":"Students who avoided the tool obtained better marks.","C":"The tool raised results in every subject.","D":"Teachers relied on the tool more than students did."}},{"n":7,"stem":"What did the student survey reveal?","group":"第5-7题","options":{"A":"The assistant was difficult to log into.","B":"Many staff had switched the assistant off.","C":"The assistant sometimes gave confident but wrong answers.","D":"The assistant collected personal data without consent."}}]},{"name":"Section B","questions":[{"n":8,"stem":"What does Ms. Aldridge say about Lena's market summary?","group":"第8-11题","options":{"A":"It was longer than she had expected.","B":"It was sent back to Lena for correction.","C":"It told the team something they did not already know.","D":"It was finished well ahead of schedule."}},{"n":9,"stem":"What went wrong at the client meeting in week seven?","group":"第8-11题","options":{"A":"Lena opened with material the client did not need.","B":"Lena spoke too quietly for the room.","C":"Lena left out the cost figures.","D":"Lena arrived without having rehearsed."}},{"n":10,"stem":"Why is there no full-time post available at present?","group":"第8-11题","options":{"A":"The design team is being cut back.","B":"The team's budget is frozen until the third quarter.","C":"Lena does not yet hold the required qualification.","D":"The account is being moved to another office."}},{"n":11,"stem":"What does Ms. Aldridge ask Lena to do?","group":"第8-11题","options":{"A":"Take over the account's paperwork.","B":"Train the next group of interns.","C":"Join the team's budget meeting.","D":"Speak at the April review with a single chart."}},{"n":12,"stem":"What does Marcus now think of his original topic?","group":"第12-15题","options":{"A":"It has already been covered in detail.","B":"It amounts to several separate studies.","C":"It cannot be researched without extra funding.","D":"It overlaps with his supervisor's own work."}},{"n":13,"stem":"What will Marcus actually study?","group":"第12-15题","options":{"A":"The design of museum websites.","B":"The way museums use social media.","C":"The short descriptions written for objects.","D":"The training given to museum guides."}},{"n":14,"stem":"What does Dr. Rowe warn him about?","group":"第12-15题","options":{"A":"Museums may refuse access to their records.","B":"Two hundred objects per museum is too small a sample.","C":"The old card indexes are badly organised.","D":"Curators are difficult to schedule for interviews."}},{"n":15,"stem":"What does Dr. Rowe advise about the literature review?","group":"第12-15题","options":{"A":"It should be cut to less than half its present length.","B":"It should be moved into an appendix.","C":"It should take in more recent studies.","D":"It should be written after the interviews."}}]},{"name":"Section C","questions":[{"n":16,"stem":"What has changed most in media work, according to the passage?","group":"第16-18题","options":{"A":"The cost of gathering news.","B":"The average length of articles.","C":"The training given to editors.","D":"The precision with which audiences can be measured."}},{"n":17,"stem":"What does the author say about the length of content?","group":"第16-18题","options":{"A":"It has fallen sharply in every format.","B":"Long formats still attract large audiences.","C":"It matters more than the shape of attention.","D":"It is now decided by the platform."}},{"n":18,"stem":"What is the author's main point in the final paragraph?","group":"第16-18题","options":{"A":"Journalists should ignore audience data altogether.","B":"Readers are less well informed than they once were.","C":"The pressure on journalists comes from measurable audience demand.","D":"Platforms should be required to publish their data."}},{"n":19,"stem":"How much vegetable does a city of a million people eat in a year?","group":"第19-21题","options":{"A":"About seventy thousand tonnes.","B":"Roughly four thousand tonnes.","C":"About one to three per cent of its rooftop area.","D":"Several square kilometres of produce."}},{"n":20,"stem":"What have studies of European and North American cities found?","group":"第19-21题","options":{"A":"Rooftop farms could supply most of a city's vegetables.","B":"Cities lack the sunlight that rooftop farming requires.","C":"Rooftop production reaches its limit far below demand.","D":"Rooftop farms take land that could be used for housing."}},{"n":21,"stem":"What is the author's view of urban agriculture?","group":"第19-21题","options":{"A":"It should give way to conventional farming.","B":"Its social benefits have been overstated.","C":"It will soon replace imported vegetables.","D":"It is worth doing for reasons beyond food supply."}},{"n":22,"stem":"What does the author say about repetition?","group":"第22-25题","options":{"A":"It explains why songs outlast faces in memory.","B":"It matters but does not fully explain musical memory.","C":"It has almost no effect on long-term memory.","D":"It works only with music heard in childhood."}},{"n":23,"stem":"Why can a melody survive damage that has erased surrounding events?","group":"第22-25题","options":{"A":"It is stored in a region of the brain that ages slowly.","B":"It carries less meaning than ordinary language.","C":"It is laid down in several connected channels.","D":"It is repeated more often than speech."}},{"n":24,"stem":"How are singing groups in care homes described?","group":"第22-25题","options":{"A":"As therapy that draws out residents who rarely speak.","B":"As entertainment organised mainly for the staff.","C":"As a treatment that reverses memory loss.","D":"As a substitute for ordinary conversation."}},{"n":25,"stem":"What does the closing sentence suggest?","group":"第22-25题","options":{"A":"Songs describe the past more accurately than speech does.","B":"The past is best left undisturbed.","C":"Words come back before melodies do.","D":"Remembering becomes an experience rather than a report."}}]}],"transcripts":{"第1-2题":["The Brant Institute has confirmed that a soft-bodied animal filmed in the Vellin Trench is a species previously unknown to science. The trench lies roughly four thousand metres below the surface of the southern Ardic Ocean, where sunlight never reaches and the water stays close to freezing. The creature, about the length of a human thumb, was first recorded three years ago by a camera mounted on a remotely operated vehicle. At the time, the team assumed it was a familiar species that had drifted far outside its normal range. Genetic comparison with two specimens collected last summer, however, showed differences too large to set aside, and the animal has now been formally described. Researchers say it feeds on bacteria that cluster around mineral vents, and that its shell has almost entirely disappeared, an adaptation that saves energy in water where calcium is scarce. A full account will appear in the institute's journal next month."],"第3-4题":["The city of Halden will remove private cars from its historic centre from the first week of April, after a council vote that ended almost two years of argument. The zone covers some forty streets around the old harbour, an area that currently handles about eighteen thousand vehicle movements a day. Delivery vans will still be admitted before ten in the morning, and residents holding a parking permit will keep access to their own street. The council has funded two new tram stops and a fleet of small electric buses that will circle the zone every eight minutes. Traders had warned that the change would push shoppers towards retail parks on the edge of the city, and the final vote was close. Officials say noise and air quality will be monitored for a full year, and that the findings will be published before the scheme is reviewed."],"第5-7题":["Ellsworth University has given every first-year student access to an artificial intelligence assistant that answers questions about course material at any hour of the day. The system was trained on lecture notes, reading lists and past examination papers, and it is designed to reply in ordinary language rather than send students to a page number. Officials describe it as a supplement to tutorials, not a replacement for them. In a trial last term involving four thousand students, those who used the assistant at least once a week were slightly more likely to submit assignments on time, although the university warns that the difference may say more about study habits than about the tool itself. Teaching staff may switch the assistant off for their own modules, and about one in five has done so. A student survey found wide approval, but also complaints that the system sometimes gave confident answers that were simply wrong."],"第8-11题":["Ms. Aldridge: Come in, Lena. Sit down. How are you feeling now that the ten weeks are over?","Lena: Honestly? A bit strange. Everyone else on the team is staying, and I'm clearing my desk.","Ms. Aldridge: Well, not quite clearing it. That's partly why I asked you in. First, the feedback. Your research was the strongest of any intern we've had this year. The market summary you did in week three is still being passed around.","Lena: That's good to hear. I was worried it was too long.","Ms. Aldridge: It was long. It was also the only one that told us something we didn't already know. Where you struggled, and you know this, was the client meeting in week seven.","Lena: I do. I had twelve slides and about four minutes.","Ms. Aldridge: You had twelve slides and four minutes, and you started with the methodology. Nobody in that room cared about methodology. They cared about whether they could afford the thing.","Lena: I've thought about that a lot since. I keep rehearsing a shorter version.","Ms. Aldridge: Good. Now, the reason I asked you in. There is no full-time position. Not yet. The budget for the design team is frozen until the third quarter, and I can't give you a date.","Lena: So that's it?","Ms. Aldridge: That's not it. I can offer you a part-time contract, twenty hours a week, starting in February, on the same account. It isn't what you applied for, and the pay is pro rata, which I know is a step down from what you'd hoped.","Lena: It's a step up from nothing.","Ms. Aldridge: That's the spirit. But I'd like something from you in return. I want you to present at the April review. Ten minutes, no slides, just you and the client.","Lena: Ten minutes with no slides? Can I use one chart?","Ms. Aldridge: One chart. That's the deal."],"第12-15题":["Dr. Rowe: So, Marcus, you wanted to talk about the proposal.","Marcus: Yes. I've been reading for about six weeks, and I think my topic is too broad. I started with how museums use digital media, which is, I realise now, about four theses.","Dr. Rowe: It is at least four. Which of the four interests you most?","Marcus: The labels. Not the websites, not the social media accounts, but the short descriptions next to the objects. I want to compare how three regional museums write them, and whether the writing changed after the collections went online.","Dr. Rowe: That's manageable. How many objects?","Marcus: That's my problem. One museum has forty thousand records.","Dr. Rowe: Then don't take all of them. Take a sample, say two hundred objects per museum, drawn the same way in each. What would you compare?","Marcus: Length, use of technical terms, whether an object's history is told as a story or as a list of facts. And I'd interview the curators who wrote them.","Dr. Rowe: The interviews will take longer than you think. Curators are, how shall I put this, generous with their time in principle and impossible to schedule in practice.","Marcus: I'd budget three months.","Dr. Rowe: Budget five. And Marcus, one more thing. You've written whether the writing changed. Changed compared with what?","Marcus: With the labels written before the collections went online. I have access to the old card indexes at two of the three.","Dr. Rowe: Then say so in the proposal, in the first paragraph, not on page nine. The committee reads the first page properly and skims the rest. Also, your literature review is currently nineteen pages.","Marcus: I know. I got carried away.","Dr. Rowe: Cut it to eight. Nobody is impressed by length. They're impressed by a question they can answer."],"第16-18题":["Ask anyone who works in media what has changed most in the past fifteen years, and the answer is rarely about technology. It is about measurement. A newspaper once knew how many copies it sold; a television channel knew roughly how many people were watching. Neither knew, with any precision, which sentence on which page had lost the reader's interest. Today that information arrives continuously, and it arrives while the work is still being made. Editors can see, minute by minute, where an audience stops scrolling, and they see it early enough to change the next piece.","The effect is not simply that content gets shorter. Length, in fact, has proved surprisingly resilient; long podcasts and lengthy essays still find large audiences. What has changed is the shape of attention. A piece now has to earn the right to be finished, and it has to do so within the first few seconds, because the platform offers an alternative at every moment. The result is a form that front-loads its most striking material, the surprising figure, the blunt claim, the anecdote, and only afterwards supplies the reasoning that would make the claim defensible.","Critics describe this as a corruption of public understanding, and there is something in that. But the criticism is often aimed at the wrong target. Audiences have always preferred to be entertained before they are informed; what is new is that the preference is now visible, countable and immediately profitable. A journalist who resists it is not resisting a machine but a measurable demand, and that is a far harder thing to argue with. The honest question is not whether the attention economy has changed the shape of what we read. It plainly has. The question is who, if anyone, is willing to pay for the version that takes longer."],"第19-21题":["Urban farming has a persuasive logic. Food grown on a rooftop travels a few hundred metres instead of a few thousand, the roof itself stays cooler, and the grower learns something about where dinner comes from. City governments have noticed, and plots have multiplied, on school grounds, in hospital courtyards and on the flat roofs of supermarkets.","The difficulty is arithmetic. A well-run rooftop farm might produce four or five kilograms of vegetables per square metre in a year. A city of a million people eats, very roughly, seventy thousand tonnes of vegetables annually. To grow even a tenth of that on roofs, you would need several square kilometres of suitably strong, flat, sunlit surface, and cities do not have several square kilometres of it in the places where people actually live. Studies of a number of European and North American cities have reached the same conclusion: the ceiling on roof-based production lies somewhere between one and three per cent of demand, and it is reached long before the land runs out.","None of this makes urban agriculture pointless. Its value is better measured in what it does to people than in what it puts in the shops. A child who has pulled a carrot out of soil understands a supply chain in a way no diagram achieves, and community plots have repeatedly been shown to widen the social contacts of people who would otherwise be isolated. There is also the question of what else the land could be used for; a rooftop garden is a poor substitute for housing, but it is an excellent use of a surface that would otherwise do nothing at all. The mistake is to treat it as a solution to food supply. It is a solution to something else, and that something else deserves to be named clearly."],"第22-25题":["Why does a song from adolescence stay in the memory when the name of a colleague met last week does not? Part of the answer is repetition: songs are designed to be heard many times, and repetition is the oldest known method of fixing material in the mind. But repetition alone does not explain the peculiar quality of musical memory, which is so often involuntary. A few bars of a tune can return a room, a smell, a person, entire, after decades in which none of it was consciously recalled.","Researchers who study this point to the way music is stored. Words are remembered largely for their meaning; music is remembered in several channels at once, pitch, rhythm, timbre and the physical memory of how it feels to sing or play it. When these channels are laid down together, each becomes a route back to the others, so a single cue can open the whole. This is why a melody heard in childhood can survive damage that has erased the events around it; patients in the later stages of memory loss will sometimes sing every word of a song learned long ago while being unable to say what day it is.","The practical use of this is younger than the science. Care homes have begun running singing groups not as entertainment but as therapy, and staff report that residents who speak very little will join a familiar chorus. The effects do not last long once the music stops, and nobody claims that singing restores memory in any general sense. What it restores is something narrower and, for the person concerned, more immediate: for the length of a verse, the past is not something being described. It is something being done."]}},"cet6-mock-l2":{"id":"cet6-mock-l2","level":"cet6","year":2026,"month":1,"set":2,"mock":true,"sections":[{"name":"Section A","questions":[{"n":1,"stem":"What does the Alderton Report conclude about adaptation spending?","group":"第1-2题","options":{"A":"It has grown for three years but meets under a fifth of estimated need.","B":"It has fallen sharply since the panel began collecting figures.","C":"It is now concentrated almost entirely on early warning systems.","D":"It has proved sufficient for the regions most exposed to risk."}},{"n":2,"stem":"According to Dr. Hale, why do some projects attract more money than others?","group":"第1-2题","options":{"A":"They are supported by farmers whose growing seasons have shifted.","B":"They produce visible structures that are simple to publicise and inspect.","C":"They can be completed within a single budget year.","D":"They cost far less than networks and training schemes."}},{"n":3,"stem":"What made photographing the collection difficult?","group":"第3-4题","options":{"A":"The pages had been torn by earlier readers.","B":"The library owned no camera able to work at an angle.","C":"Many of the bindings crumbled as soon as they were opened.","D":"The ink in the margins had faded beyond recovery."}},{"n":4,"stem":"What does Marcus Feld's remark suggest about releasing the images free of charge?","group":"第3-4题","options":{"A":"He expects scholars to pay for high-resolution copies later.","B":"He sees it as a risk that heavy use will justify the expense.","C":"He believes registration would have discouraged researchers.","D":"He doubts that the collection will attract much attention."}},{"n":5,"stem":"What was the main purpose of the first-stage trial?","group":"第5-7题","options":{"A":"To compare two doses of the compound.","B":"To measure how far patients could walk in six minutes.","C":"To establish that the compound was safe to take.","D":"To recruit patients for a much larger study."}},{"n":6,"stem":"What does the research director say about the walking-distance result?","group":"第5-7题","options":{"A":"It was smaller than the designers had expected.","B":"It may not last beyond the twelve weeks of the trial.","C":"It was recorded mainly in patients given the placebo.","D":"It disappeared when the dose was reduced."}},{"n":7,"stem":"What is planned for the autumn?","group":"第5-7题","options":{"A":"Recruitment for a trial at eleven centres.","B":"Publication of the full results of the first trial.","C":"A review of the side effects reported by volunteers.","D":"Approval of the compound for general use."}}]},{"name":"Section B","questions":[{"n":8,"stem":"What does Tobias report about the keynote speaker?","group":"第8-11题","options":{"A":"She has asked to be replaced by a colleague.","B":"She has agreed to speak for a reduced fee.","C":"She has withdrawn without suggesting anyone else.","D":"She has asked for her lecture to be moved."}},{"n":9,"stem":"Why is Ellen worried about the replacement?","group":"第8-11题","options":{"A":"The replacement has never published on the conference theme.","B":"Registrations may have been driven by the original speaker's reputation.","C":"The replacement cannot travel in April.","D":"The programme has already gone to press."}},{"n":10,"stem":"What do they decide to do about the parallel sessions?","group":"第8-11题","options":{"A":"Reduce the number of papers accepted.","B":"Add a fifth room to take the overflow.","C":"Cut each paper to fifteen minutes and appoint a discussant.","D":"Spread the sessions over an extra day."}},{"n":11,"stem":"How do they plan to pay the discussants?","group":"第8-11题","options":{"A":"By raising the registration fee.","B":"From the budget already set aside for travel grants.","C":"By charging the publisher for the programme.","D":"With money freed because printing is now covered."}},{"n":12,"stem":"Why does Daniel want to leave his laboratory job?","group":"第12-15题","options":{"A":"He has lost interest in the science itself.","B":"He finds the hours at the bench exhausting.","C":"He enjoys explaining research to the public more than bench work.","D":"He has been offered a better-paid post elsewhere."}},{"n":13,"stem":"What does Grace say matters most about his first pieces of writing?","group":"第12-15题","options":{"A":"That they appear in a well-known publication.","B":"That they are edited by someone competent.","C":"That they are written within a single month.","D":"That they cover the whole of his research field."}},{"n":14,"stem":"What is wrong with Daniel's comparison about pay?","group":"第12-15题","options":{"A":"It ignores the cost of moving to another city.","B":"It relies on figures that are several years out of date.","C":"It sets a starting salary against one he would reach after four years.","D":"It assumes his salary would never rise again."}},{"n":15,"stem":"What does Grace advise Daniel to do?","group":"第12-15题","options":{"A":"Resign and look for work in science writing at once.","B":"Ask for a four-day week and build a portfolio over a year.","C":"Apply for a post at a learned society instead.","D":"Take a course in journalism before applying."}}]},{"name":"Section C","questions":[{"n":16,"stem":"What assumption do universities commonly make about critical thinking?","group":"第16-18题","options":{"A":"That it will develop on its own once students know enough.","B":"That it can be taught without any subject knowledge.","C":"That it is best developed in very small classes.","D":"That examinations already reward it generously."}},{"n":17,"stem":"What is the point of asking students to list the claims both accounts accept?","group":"第16-18题","options":{"A":"It teaches them to choose the stronger side quickly.","B":"It shows that disagreement rests on a narrow base of shared fact.","C":"It removes the need for a teacher's judgement.","D":"It proves that one of the accounts must be false."}},{"n":18,"stem":"What obstacle does the author identify?","group":"第16-18题","options":{"A":"A shortage of staff able to mark written work.","B":"The cost of buying new teaching technology.","C":"Departments' reluctance to give up time now spent on content.","D":"Students' unwillingness to read opposing views."}},{"n":19,"stem":"What is the main weakness of regulating individual machines?","group":"第19-21题","options":{"A":"The limits cannot be checked with a meter.","B":"It ignores the combined effect of many legal sources.","C":"It places too heavy a burden on small shops.","D":"It applies only to refrigeration units."}},{"n":20,"stem":"Why is measuring noise difficult?","group":"第19-21题","options":{"A":"Meters cannot record sound at a bedroom window.","B":"Residents report noise that instruments cannot detect.","C":"A short reading misses intermittent events and seasonal change.","D":"Legal limits differ from one street to the next."}},{"n":21,"stem":"What is the political disadvantage of zone-based regulation?","group":"第19-21题","options":{"A":"It makes the total amount of noise invisible.","B":"It requires councils to buy equipment they cannot afford.","C":"It has been rejected by the courts.","D":"It means telling some people their share must shrink."}},{"n":22,"stem":"What does the author say is wrong with the debate on machines and jobs?","group":"第22-25题","options":{"A":"It assumes that machines will take most jobs.","B":"It concentrates on the number of jobs rather than their shape.","C":"It relies on figures supplied by employers.","D":"It ignores the views of clerical workers."}},{"n":23,"stem":"What pattern has been visible so far?","group":"第22-25题","options":{"A":"A hollowing out of middle-skill clerical and technical work.","B":"A general rise in unemployment across all levels.","C":"The collapse of firms that automate their claims.","D":"A transfer of judgement work to junior staff."}},{"n":24,"stem":"What long-term consequence is described in the third paragraph?","group":"第22-25题","options":{"A":"Firms find they have no internal candidates for senior roles.","B":"Entry-level workers begin to demand higher salaries.","C":"Supervisors are themselves replaced by automated systems.","D":"Customers lose confidence in automated decisions."}},{"n":25,"stem":"What does the author recommend?","group":"第22-25题","options":{"A":"Preserving jobs that no longer need doing.","B":"Delaying automation until all staff are retrained.","C":"Rebuilding entry-level routes such as apprenticeships.","D":"Raising salaries in occupations facing shortages."}}]}],"transcripts":{"第1-2题":["A report published today by the Alderton Panel on Climate Finance concludes that spending on adaptation has risen for a third consecutive year, yet still covers less than a fifth of what the most exposed regions are estimated to need. The panel, made up of twelve economists and engineers, examined public budgets in forty-one countries. It found that money is increasingly directed towards sea walls and drainage systems, while far less is committed to early warning networks and to the retraining of farmers whose growing seasons have shifted. Dr. Nina Hale, who chaired the panel, said the imbalance was not accidental. Projects that produce a visible structure, she argued, are easier to announce and easier to audit than projects whose benefits depend on habits changing slowly over a decade. The report recommends that donors tie a fixed share of every adaptation grant to monitoring and to local training, and that progress be reviewed every two years rather than every five. Governments are expected to respond at a meeting in March."],"第3-4题":["Caldwell Library has completed a four-year project to photograph and publish its collection of medieval medical manuscripts, some of which have not been handled by anyone outside the library for more than a century. The collection consists of eighty-three volumes, many of them bound in covers that crumble at the hinge the moment they are opened. Rather than flattening the pages against a glass plate, the conservation team built a foam cradle for each volume, so that it could be photographed at an angle of no more than forty degrees. Every image was then checked by two readers working independently, because faded ink in the margins is easily mistaken for damage. The library has released the images without charge and without registration, a decision its director, Marcus Feld, described as a bet that use will justify the cost. Scholars have already begun to compare recipes for pain relief across the volumes, and a group in Veymouth reports that one instruction long dismissed as nonsense appears to describe a workable antiseptic."],"第5-7题":["A small biotechnology company has reported the results of a first-stage trial of a compound intended to slow the loss of muscle strength in patients with a rare inherited disorder. The trial enrolled thirty-six volunteers and lasted twelve weeks. Because the purpose of such a study is to establish safety rather than benefit, the primary measure was the number and severity of side effects; on that measure the compound performed acceptably, with headaches the most common complaint and no participant withdrawing. Secondary measures were more encouraging than the designers had expected. Patients who received the higher dose walked, on average, sixty metres further in six minutes than they had at the start, while those given the placebo changed hardly at all. The company's research director cautioned that the groups were small, that the trial had not been designed to compare doses, and that a twelve-week improvement may not persist. A second-stage trial, involving four hundred patients at eleven centres, is due to begin recruiting in the autumn."],"第8-11题":["Ellen: Tobias, have you read the latest message from the keynote speaker? Tobias: Only the first line. She has pulled out. Family reasons, apparently, and she suggests her deputy instead. Ellen: Her deputy. The one who wrote the book on harbour towns? Tobias: That is the one. I have read two of her chapters and they are sharp, but she is far less known. Half the registrations we have had so far probably came because of the original name. Ellen: Then we must decide this week, before the programme goes to press. If we announce the change now and explain why, people will accept it. If they discover it in April from the website, they will not. Tobias: Agreed. The other problem is the parallel sessions. We have nineteen papers and four slots, which means five papers in some rooms. Ellen: Five is too many. Twenty minutes each leaves no time for questions, and the questions are the reason people come. Tobias: We could shorten the papers to fifteen minutes and add a discussant to each session. That keeps the numbers and still leaves room for argument. Ellen: It also means finding eight discussants who will actually read the papers beforehand. Last time half of them arrived having skimmed the abstract. Tobias: We could pay them. Not much, but enough to make it a commitment rather than a favour. Ellen: Out of which budget? The travel grants are already stretched. Tobias: The publisher has offered to cover the printing of the abstract book. That frees about two thousand, and it is not a sum that would change anyone's travel plans. Ellen: All right. But I want the discussants named in the programme, so that if they do not deliver, it is visible. Tobias: Fair. And the poster session? Do we keep it on Thursday evening? Ellen: Move it to Friday lunchtime. People will actually walk past the posters if there is food."],"第12-15题":["Grace: So, Daniel, you said on the form that you are thinking of leaving the laboratory. What is pulling you away? Daniel: It is not the science. I like the science. It is that I spend six hours a day at a bench, and the part of the week I look forward to is explaining the work to visitors. Grace: Then let us take that seriously rather than treating it as a hobby. Have you written anything for a general audience? Daniel: A few pieces for the department newsletter. Nothing that anyone would call a portfolio. Grace: That is the first gap to close, and it is the cheapest one. Three or four short pieces, published somewhere with an editor who will cut them. The editing matters more than the publication. Daniel: I have been put off by the pay. Everyone I have spoken to says science writing pays badly at the start. Grace: It does, for the first two years. But you are comparing a starting salary with the salary you would reach in four years if you stayed. That comparison always looks bad, and it is the wrong one. Daniel: So what is the right one? Grace: Whether the ceiling is higher, and whether you can live on the floor for a while. Do you have savings? Daniel: About four months' worth. Grace: Then do not resign. Ask for a four-day week, use the fifth day for writing, and give yourself a year. If by next summer you have six published pieces and no income from them, you will know something. Daniel: And if I do have income? Grace: Then you negotiate from strength rather than from hope. One more thing: talk to people doing the job now, not to people who left it five years ago. The work has changed."],"第16-18题":["Universities routinely list critical thinking among their graduate aims, and just as routinely assume that it will appear once students have acquired enough subject knowledge. The assumption is convenient, because it requires no change to the timetable. It is also largely unsupported. Studies that follow students through a degree find that the ability to weigh evidence improves modestly at best, and that most of the improvement occurs in departments where argument is taught explicitly rather than absorbed by example. What explicit teaching looks like is less mysterious than the phrase suggests. In one design, students are given two accounts of the same event, written from opposing positions, and asked to list the claims that both accounts accept. The exercise is uncomfortable, because most students arrive expecting to choose a side. Its value lies in showing that disagreement usually rests on a narrow base of shared fact, and that identifying that base is a skill which can be practised. A second design asks students to write the strongest version of the argument they reject. This is harder still, and it exposes a common failure: students can often state an opposing view, but they state it in a form no reasonable person would hold, which makes refutation easy and learning impossible. None of this requires smaller classes or new technology. It requires that the reasoning be made visible, that students be asked to produce it under conditions they cannot avoid, and that someone with expertise mark the result. The obstacle is not money but the reluctance of departments to surrender time currently spent on content. Content, after all, is what examinations reward."],"第19-21题":["Most cities now regulate the noise of individual machines: a lorry, a drill, a ventilation unit must each stay below a stated limit. The approach has an obvious appeal, since a limit can be written into a permit and checked with a meter. It also fails to address the problem residents actually complain about, which is the sum of many sources that are each perfectly legal. A street may contain a dozen refrigeration units, each quiet enough to pass inspection, whose combined hum at three in the morning is what wakes the people living above the shop. No single owner is responsible, and no inspector has the authority to require that any one of them be switched off. Regulation designed around sources cannot see a total. The second difficulty is measurement. A reading taken at a bedroom window over ten minutes will miss the delivery that arrives at half past five, and it will also miss the fact that a sound tolerable in July, with windows open, is intolerable in January, when the same plant runs all night. Averaging over time produces numbers that are defensible in court and meaningless to the person who cannot sleep. Some cities have begun to regulate zones rather than machines, setting a ceiling for an area and then allocating it, much as a cap on emissions is allocated among firms. The advantage is that it makes the total visible and forces a decision about who must reduce. The disadvantage is political: allocating a scarce resource means telling someone that their share is smaller than they had assumed, and few councils relish that conversation before an election."],"第22-25题":["Arguments about artificial intelligence and employment tend to be conducted in totals: either machines will take most jobs, or they will take very few. Both claims are probably wrong, and both are unhelpful, because what matters is not the number of jobs but their shape. The pattern visible so far is not mass dismissal but the hollowing out of the middle. Tasks that can be described precisely enough to be automated tend to be the tasks of clerical and technical workers, whose jobs consist of applying known rules to known cases. The work that remains at the top involves judgement under uncertainty, and the work at the bottom involves physical presence in unpredictable settings. A firm that automates its claims processing does not usually close; it hires fewer clerks and more people who can supervise the system and explain its decisions to customers and regulators. The consequence is a change in the ladder rather than the disappearance of the building. Entry-level positions have traditionally been where people learned the judgement that the higher positions require. If the entry-level task is automated, the learning is removed along with it, and firms discover after several years that they have no internal candidates for roles they assumed would fill themselves. This is not an argument for preserving jobs that no longer need doing. It is an argument for rebuilding the bottom rung deliberately, through apprenticeships, through supervised projects, and through a willingness to employ people before they are fully productive. The cost of doing so is visible on a budget line; the cost of not doing so appears a decade later, in the form of a shortage that no salary seems able to fill."]}}};
var CET_LISTEN_ANSWERS = {"cet4-mock-l1":{"1":"B","2":"C","3":"B","4":"C","5":"A","6":"B","7":"A","8":"B","9":"A","10":"B","11":"A","12":"A","13":"C","14":"A","15":"A","16":"B","17":"B","18":"C","19":"A","20":"B","21":"B","22":"B","23":"B","24":"B","25":"A"},"cet4-mock-l2":{"1":"B","2":"C","3":"B","4":"A","5":"D","6":"A","7":"C","8":"B","9":"C","10":"D","11":"A","12":"B","13":"C","14":"D","15":"A","16":"C","17":"B","18":"A","19":"D","20":"B","21":"A","22":"C","23":"A","24":"B","25":"D"},"cet6-mock-l1":{"1":"A","2":"B","3":"A","4":"C","5":"B","6":"A","7":"C","8":"C","9":"A","10":"B","11":"D","12":"B","13":"C","14":"D","15":"A","16":"D","17":"B","18":"C","19":"A","20":"C","21":"D","22":"B","23":"C","24":"A","25":"D"},"cet6-mock-l2":{"1":"A","2":"B","3":"C","4":"B","5":"C","6":"B","7":"A","8":"A","9":"B","10":"C","11":"D","12":"C","13":"B","14":"C","15":"B","16":"A","17":"B","18":"C","19":"B","20":"C","21":"D","22":"B","23":"A","24":"A","25":"C"}};
var CET_LISTEN_EXPS = {"cet4-mock-l1":{"1":"答案 B。新闻第一句说图书馆把开放时间延长到晚上十点，并把二楼的旧储藏室改成夜间自习区；A 项的搬迁、C 项的收费在原文中都没有出现。","2":"答案 C。原文说座位必须在网上预订，每次限三小时；只要有借书证就能进入，并不要求是在校全日制学生，D 项的日收费也不存在。","3":"答案 B。第二句说明材料主要由收割后剩下的谷秆纤维混合少量植物胶制成；A、C、D 三种原料原文均未提及。","4":"答案 C。指导老师说最难的不是让材料够结实，而是把成本降到能与普通塑料膜竞争；B 项正是他明确排除的那一项。","5":"答案 A。原文说从早上五点到下午四点，旧桥到北门之间的河滨路禁止车辆通行；B 项的七点半是比赛开始时间，不是封路时段。","6":"答案 B。原文说住在封闭区域内的居民可以领取车辆通行证，但必须在周五之前到社区办公室领取；D 项的当天网上申请与原文相反。","7":"答案 A。最后一句建议司机改走环路，并在周日多预留三十分钟；B、C 两项只是把文中出现的地点与公交临时改线错当成了建议。","8":"答案 B。Mia 一开口就说明自己是为下学期的选课计划而来（trying to work out my course plan），学分只是随后的话题；A 项是教授自己的猜测，当场被她否定。","9":"答案 A。她说自己已修满 62 学分，毕业要求 120 学分，所以还差 58 学分；B 项的 62 是已修学分，C 项的 120 是毕业总要求。","10":"答案 B。教授说写作课每学期都开，统计课只在秋季开，所以要先修统计；A、D 两项关于难易的说法在原文中找不到依据。","11":"答案 A。教授说语言学导论是后面两门课的先修课，这也是他建议她选这门课的理由；他还说第二周退课不受处罚，C 项与原文相反。","12":"答案 A。女生说房东把月租从 450 涨到了 480；B 项账单要另付，C 项原文说的是比宿舍便宜而不是比预期便宜，D 项未提及。","13":"答案 C。男生担心真住到一起会变成他天天做饭、对方一周只打扫一次，也就是家务分不公平；A、B、D 三项在对话中都没有出现。","14":"答案 A。两人把家务列成六项，各认领三项，并且每月互换一次；B 项请人打扫、C 项由女生包下做饭都与他们的约定不符。","15":"答案 A。他们约定工作日晚上十一点以后不留客人，并且谁请来的客人谁负责额外打扫；B 项说周末一律不许客人，与原文相反。","16":"答案 B。讲话者说读公司资料只是一半，另一半是准备能支撑回答的具体事例，而这恰恰是多数考生忽略的；A 项是他们已经在做的事。","17":"答案 B。原文说录一次音，留意自己在哪里放慢或重新开口，那些地方通常说明故事还没讲清楚；A、C 两项不是录音的目的，D 项更无从谈起。","18":"答案 C。最后一段建议问团队去年遇到了什么困难，或者前六个月的成功如何衡量；A、B 两项正是他明确排除的问题。","19":"答案 A。开头说研究者指出睡眠的时间点与睡眠长度同样重要；B、C、D 三项都是原文没有提到的因素。","20":"答案 B。原文说生物钟被推后时，人们常在早上注意力差、在奇怪的时间感到饥饿；A 项“需要更少睡眠”在原文中没有任何依据。","21":"答案 B。讲话者说睡前避开亮屏不是因为光线本身有害，而是因为它让大脑停留在白天的状态；A 项的伤眼说法被他明确否定了。","22":"答案 B。第二段说第一周就有自行车横在门口、堵住轮椅坡道，学校因此出台规定；A、C 两项原文没有提到，D 项是规定出台之后才被禁止的行为。","23":"答案 B。原文说多次违规会导致账号被停用一个月；A 项的押金、C 项的周末禁骑、D 项的通报院系都是编造的。","24":"答案 B。原文说刹车坏了的车应立刻通过应用报修，这一程免费；D 项自费修理与原文相反，C 项也没有要求把车送到公司。","25":"答案 A。最后一句说规定实施后校园事故减少了三分之一；B 项把报修的原因当成了事故原因，C、D 两项的数字与地点都是编造的。"},"cet4-mock-l2":{"1":"答案 B。新闻第二句说两个主食堂将不再随外卖提供塑料刀叉勺，想用餐具的人要在柜台领一套可重复使用的餐具并付两美元押金；A 项停止外卖、C 项提高饮品价格在原文中都没有出现。","2":"答案 C。第一段末句负责人 Dana Whitfield 承认押金制度在最初几周可能让打饭队伍变慢，因此会增派人手帮忙；B、D 两项的担心原文未提。","3":"答案 B。第一段末句说课程结束时每个学员都会做出一个关于自己关心话题的小网页；A 项的笔试、C 项为慈善机构做手机应用都属于无中生有。","4":"答案 A。末段 Peter Nash 说去年夏天完成课程的学生中有一半以上后来在学校选修了计算机课；B 项三个教室、C 项企业赞助与原文不符。","5":"答案 D。第一段说市议会表示目的是给居民提供下班后散步和锻炼的地方，尤其针对白天高温的夏季；A 项音乐节、B 项吸引游客均未提及。","6":"答案 A。第二段说划船区和儿童游乐场仍将在八点关闭，因为每晚要检查设备；B 项保安增派、C 项沿湖新装路灯都是已经发生的变化。","7":"答案 C。第三段说东门附近居民写信给议会，认为深夜噪音和停车问题可能变得更糟；A 项路灯费用、D 项设备状况都不是投诉内容。","8":"答案 B。对话开头 Kevin 说自己想加入健身房但不知从何开始，随后询问会员种类；A 项订课是在了解会员类型之后才提到的。","9":"答案 C。Sophie 说基础会员五十美元，只包含器械房和泳池，不含课程；B 项并非全价的一半（九十的一半是四十五），D 项的年级限制原文没有。","10":"答案 D。Sophie 说初学者健身课每组最多十二人，方便教练检查每个人的动作；A 项每周两次说的是动感单车课，B 项体能测试原文未提。","11":"答案 A。对话结尾 Kevin 听说周五前报名可享九折后说 I will come in tomorrow，说明他打算去办全价会员；B、C 两项他只是打听，并未决定。","12":"答案 B。Tom 说往返海边的车票每人八十美元，比他预想的贵；D 项与 Rachel 说去年约五十美元相矛盾。","13":"答案 C。Rachel 追问 Is it, you know, shared rooms，得知四人一间后表示犹豫；B 项旅馆距海边步行二十分钟，算不上太远。","14":"答案 D。Tom 说先别订船票，等看了天气再说，Rachel 表示赞同，即天气好才去；A 项与不提前预订的说法相反。","15":"答案 A。结尾 Rachel 问要不要今晚就把旅馆的便宜床位订下来，Tom 说 Yes, do it，所以今晚订床位；B 项买火车票由 Tom 明天去办。","16":"答案 C。第一段说逐字照抄幻灯片句子的笔记当时显得有用，一个月后却几乎毫无用处；A、B 两项在原文中没有依据。","17":"答案 B。第二段说用自己的话改写时大脑必须处理这个观点，正是这份努力把内容记牢；D 项保留老师原话恰恰与原文相反。","18":"答案 A。第四段说课后二十四小时读一遍胜过考前一周读五遍，因为遗忘已经开始，回忆需要费力；C 项耗时一小时原文未提。","19":"答案 D。第二段开头作者说自己报名主要是出于愧疚，也就是觉得自己应该做点什么；A 项朋友只是分享感受，并没有劝说她。","20":"答案 B。第二段末句说作者带着一身洋葱味回家，心里想着还要不要再去，说明她并不确定；A 项与没人道谢、没人问她名字的说法相反。","21":"答案 A。末段说志愿服务给她一周的生活定下了节奏，周六上午从需要打发的时间变成了她期待的部分；B、D 两项原文没有提到。","22":"答案 C。第二段说三十天期限很常见，但有些商家从下单当天算起，这样会少掉一周时间；A 项与各家规则差别很大相矛盾。","23":"答案 A。第二段说室内试穿一次的鞋子通常可以退，鞋底沾泥则不行；B 项香水味、C 项吊牌已拆都属于通常被拒收的情况。","24":"答案 B。第三段说预付面单很方便，但费用有时会从退款里扣掉；C 项耗时更长是普通邮寄的缺点，不是预付面单的问题。","25":"答案 D。末段说包裹确实会丢失，一张封好的箱子且面单清晰的照片能迅速解决争议；A 项证明箱内物品并不是拍照的目的。"},"cet6-mock-l1":{"1":"答案 A。新闻首句说 Brant Institute 确认在 Vellin 海沟拍到的软体动物是此前科学界未知的物种；B 项把研究船的深潜当成新闻主体，C 项与后文「原以为是已知物种、实为新种」正好相反。","2":"答案 B。原文说当时团队以为那是一种漂出正常分布范围的熟悉物种，直到与两份标本做基因比对才改判；A 项把它说成只有几张照片，C 项归因于颜色，原文均无此说。","3":"答案 A。新闻开头说 Halden 将从四月第一周起把私家车清出历史城区；B 项把「上午十点前允许送货」夸大成全面禁止，C 项与「持停车许可的居民仍可使用自家街道」相矛盾。","4":"答案 C。原文说商家此前警告这一变化会把顾客推向城市边缘的零售园区；A、B 两项提到的电车运营成本和送货时间都不是商家担忧的内容。","5":"答案 B。新闻说学校给每位大一学生开通了可全天候提问的 AI 助手；C 项与「是辅导课的补充而非替代」相反，D 项把训练材料之一说成唯一用途。","6":"答案 A。原文提到上学期四千名学生的试验中，每周至少使用一次的人更可能按时交作业，同时提醒差异也许更多反映学习习惯；B 项把方向说反，C 项的「每门课都提高」属过度推断。","7":"答案 C。末句说学生调查总体认可，但也抱怨系统有时很自信地给出错误答案；B 项把「两成教师自行关闭功能」误当成调查结论。","8":"答案 C。主管评价那份市场摘要时说，它是唯一一份告诉他们一些原本不知道的东西的报告；A 项只承认篇幅长，并未肯定其价值，B 项在原文没有对应。","9":"答案 A。第七周的客户会上她用四分钟讲十二页，而且从方法论讲起，主管说在场的人只关心能不能负担；B、C、D 三项在原文都找不到依据。","10":"答案 B。主管明确说设计团队的预算冻结到第三季度，所以暂时没有全职岗位；A 项「裁员」和 C 项「资格不够」都与原文不符。","11":"答案 D。对话结尾主管提出交换条件，让她在四月评审会上向客户做十分钟陈述，最多用一张图表；B 项是聘用方案本身，不是交换条件，A、C 均未提及。","12":"答案 B。Marcus 说自己从「博物馆如何使用数字媒介」起步，现在意识到那足够写四篇论文；A 项「已有充分研究」与 D 项「与导师课题重叠」都没有依据。","13":"答案 C。他说自己真正感兴趣的是展品旁边那些简短的说明文字，并想比较三家地区博物馆的写法；A、B 正是他主动排除掉的方向。","14":"答案 D。导师提醒他访谈策展人会比预想更费时，原则上慷慨、实际排期极难，并让他把三个月改成五个月；A、B、C 都不是导师的提醒。","15":"答案 A。导师说文献综述现在有十九页，要求砍到八页，还说没有人会因篇幅长而佩服你；B 项「移入附录」、C、D 均无对应内容。","16":"答案 D。文章开头说媒体最大的变化不在技术而在「测量」：过去只知道销量，如今能逐分钟看到读者在哪一句离开；A、B、C 都是被作者否定的方向，第二段还明确说篇幅并未明显变短。","17":"答案 B。第二段说长度其实相当顽强，长播客与长文仍有大量受众，真正改变的是注意力的形状；A 项与原文相反，C 项颠倒了轻重关系。","18":"答案 C。末段说受众一向喜欢先被娱乐再被告知，如今这种偏好变得可见、可计数、可立即变现，记者抵抗的不是机器而是可测量的需求；A 项是作者反对的极端做法，B、D 均非本段主旨。","19":"答案 A。第三段给出估算：百万人口的城市一年大约吃掉七万吨蔬菜；B 项数字是文中没有的，C 项把屋顶产量的上限误当成消费量。","20":"答案 C。原文说多项欧美城市研究得出同一结论：屋顶种植的上限只占需求的百分之一到三，而且远在土地用尽之前就到顶；A 项与结论相反，D 项是文章后面另提的问题。","21":"答案 D。作者说城市农业的价值更适合用「对人做了什么」来衡量，还提到社区菜园扩大社交，并提醒不要把它当成粮食供给的解决方案；A 项过于否定，B 项与作者肯定其社会价值相反。","22":"答案 B。第三段开头承认重复是最古老的记忆手段，紧接着说重复本身无法解释音乐记忆那种不由自主的特性；A 项把「歌曲比面孔记得牢」当成重复的功劳，属因果错置，C 项与原文相反。","23":"答案 C。原文说音乐同时以音高、节奏、音色和身体动作等多条通道储存，通道之间互为线索，所以一个提示就能带出整体；A 项「脑区老化慢」和 B 项「意义更少」都不是原文的解释。","24":"答案 A。文章说养老院办合唱团不是娱乐而是治疗，很少开口的住户也会跟着唱；C 项与「无人主张唱歌能普遍恢复记忆」相反，D 项把它说成日常对话的替代品。","25":"答案 D。末句说在一段歌的时间里，过去不再是被描述的对象，而是被实践的东西，即记忆成为亲身经历而非复述；A 项谈准确性，B、C 两项与句意无关。"},"cet6-mock-l2":{"1":"答案 A。新闻首句说适应支出已连续第三年上升，却仍不足最脆弱地区所需的两成；D 项与「不足五分之一」直接相反，B 项方向也相反。","2":"答案 B。Dr. Hale 指出能造出可见结构的项目更容易宣布、更容易审计，即更容易宣传与核查；A 项把报告建议中的农民培训误当成受资助对象。","3":"答案 C。原文说许多书册的封面一打开就在折页处碎裂，保护团队才为每册特制泡沫托架；D 项把「页边褪色墨迹易被误认为破损」曲解为墨迹无法复原。","4":"答案 B。Marcus Feld 把免费开放称为一场赌，赌的是使用量能证明这笔开销值得，可见他视其为有风险的决定；A 项原文未提日后收费。","5":"答案 C。原文明确说这类研究的目的是确立安全性而非疗效，主要指标是副作用的数量与严重程度；B 项只是次要指标，D 项属于下一阶段。","6":"答案 B。研究主管提醒受试组人数少、试验并非为比较剂量而设计，且十二周的改善未必能持续；A 项与「比设计者预期更令人鼓舞」相反。","7":"答案 A。末句说第二阶段试验将在十一个中心招募四百名患者，秋季开始招募；D 项把早期试验误推为已获批上市。","8":"答案 A。Tobias 说主旨演讲者已经退出，并提出由她的副手代替；C 项与「提出替代人选」矛盾。","9":"答案 B。Ellen 说目前已报名的人多半是冲着原来的名字来的，即原演讲者的声望带动了注册；D 项与「节目单尚未付印」相反。","10":"答案 C。两人商定把每篇报告压缩到十五分钟，并为每场增设一位评议人；A 项是原文讨论过但未采纳的做法。","11":"答案 D。Tobias 说出版社愿意承担摘要集的印刷费，由此腾出约两千，正好用来支付评议人；B 项是 Ellen 明说已经吃紧的预算。","12":"答案 C。Daniel 说让他期待的是向参观者解释研究工作，而不是放弃科学本身；A 项与「我喜欢这门科学」相反。","13":"答案 B。Grace 说编辑比发表更重要，即需要有称职的编辑替他删改；A 项正是她刻意淡化的发表平台。","14":"答案 C。Grace 指出他拿起薪去比留下来四年后才能达到的薪水，这种比较永远是错的；B 项原文未提数据过时。","15":"答案 B。Grace 建议他不要辞职，而是申请每周工作四天，用第五天写作，并给自己一年时间；A 项与「不要辞职」直接冲突。","16":"答案 A。首段说大学普遍假定学生有了足够学科知识后批判性思维自然出现，作者随即指出这一假定缺乏依据；C 项是末段明确否定的条件。","17":"答案 B。第二段说该练习的价值在于显示分歧建立在很窄的共同事实之上，而识别这一共同基础是可训练的技能；A 项与「学生原以为要选边」的用意相反。","18":"答案 C。末段说障碍不在经费，而在各系不愿放弃目前用于讲授内容的时间；B 项被「不需要新技术」直接排除。","19":"答案 B。第二段以制冷机组为例，说明每台都合法、合起来却吵醒住户，而按声源设计的法规看不到总量；A 项与「可用仪器检查」相反。","20":"答案 C。第三段说十分钟的读数会漏掉清晨的送货，也漏掉冬夏感受的差异，因此平均值在法庭上站得住，对失眠者却毫无意义；B 项原文未提。","21":"答案 D。末段说分区管理要告诉某人他的份额比预想的小，而议会不愿在选举前做这件事；A 项与「让总量可见」相反。","22":"答案 B。首段说争论总在总数上进行，而真正重要的是工作的形状而非数量；A 项只是作者所反对的一方观点。","23":"答案 A。第二段说可见的模式不是大规模裁员，而是中间被掏空，被自动化的正是文书与技术类岗位；C 项与「公司通常不会关门」相反。","24":"答案 A。第三段说入门岗位本是学习判断力的地方，一旦被自动化，这条学习路径随之消失，若干年后企业发现自己没有内部人选可提拔；B 项原文未提。","25":"答案 C。末段主张有意重建最底层的台阶，途径包括学徒制和有指导的项目；A 项是作者明确不赞成的做法。"}};
